/* ================= Cisco IOS simulator: CCNP show commands and running-config ================= */
(function(){
const {ip4s,lenMask,wild,ifShort,ifType,pfx,inNet,rib,INV}=IOS;
const C=IOS.C2;const S=(pat,fn,o)=>C("exec","show "+pat,fn,o);
const pad=(s,n)=>String(s).padEnd(n),rpad=(s,n)=>String(s).padStart(n);
const upt="00:14:07";
const lineUp=(w,d,i)=>IOS.lineUp(w,d,i);

/* ---------- VRF ---------- */
const vrfIfs=(d,v)=>Object.values(d.ifs).filter(i=>i.vrf===v).map(i=>ifShort(i.name));
S("ip route vrf <w>",(d,a,o)=>d.vrfs[a[0]]?IOS.showRouteFn(o.x.w,d,null,a[0]):`% IP routing table ${a[0]} does not exist`);
S("ip route bgp",(d,a,o)=>IOS.showRouteFn(o.x.w,d,"bgp"));
S("ip route <ip> <ip>",(d,a,o)=>{const w=o.x.w;let len=0,m=a[1];for(let k=31;k>=0;k--)if((m>>BigInt(k))&1n)len++;const r=rib(w,d,4).find(r=>!r.local&&r.n===a[0]&&r.len===len);if(!r)return "% Subnet not in table";
  const src=r.code==="C"?"connected":r.code==="S"?"static":r.code==="B"?"bgp "+(d.bgp?.asn||""):"ospf "+(d.ospf?.pid||1);
  return [`Routing entry for ${ip4s(r.n)}/${r.len}`,`  Known via "${src}", distance ${r.ad}, metric ${r.metric}${r.code==="O"&&r.via.some(v=>v.oif==="Null0")?", type intra area":""}`,`  Routing Descriptor Blocks:`,...r.via.map((v,k)=>`  ${k===0?"* ":"  "}${v.nh!=null?ip4s(v.nh)+(v.oif?", via "+v.oif:""):"directly connected, via "+v.oif}`),`      Route metric is ${r.metric}, traffic share count is 1`].join("\n")});
S("vrf",(d)=>["  Name                             Default RD            Protocols   Interfaces",...Object.entries(d.vrfs).map(([n,v])=>"  "+pad(n,33)+pad(v.rd||"<not set>",22)+pad(v.af4||v.legacy?"ipv4":"",12)+vrfIfs(d,n).join(" "))].join("\n"));
S("vrf brief",(d)=>["  Name                             Default RD            Protocols   Interfaces",...Object.entries(d.vrfs).map(([n,v])=>"  "+pad(n,33)+pad(v.rd||"<not set>",22)+pad(v.af4||v.legacy?"ipv4":"",12)+vrfIfs(d,n).join(" "))].join("\n"));
S("ip vrf",(d)=>["  Name                             Default RD            Interfaces",...Object.entries(d.vrfs).map(([n,v])=>"  "+pad(n,33)+pad(v.rd||"<not set>",22)+vrfIfs(d,n).join(" "))].join("\n"));
S("ip vrf interfaces",(d,a,o)=>["Interface              IP-Address      VRF                              Protocol",...Object.values(d.ifs).filter(i=>i.vrf).map(i=>pad(ifShort(i.name),23)+pad(i.ip!==null?ip4s(i.ip):"unassigned",16)+pad(i.vrf,33)+(lineUp(o.x.w,d,i)?"up":"down"))].join("\n"));

/* ---------- tunnels and crypto ---------- */
IOS.tunDetail=(w,d,i)=>{const t=i.tun||{};const src=IOS.tunSrc(w,d,i);const peer=IOS.tunPeers(w,d.name,i.name)[0];
  const L=[`  MTU 17912 bytes, BW 100 Kbit/sec, DLY 50000 usec,`,`     reliability 255/255, txload 1/255, rxload 1/255`,`  Encapsulation TUNNEL, loopback not set`,`  Keepalive ${i.keepalive?"set ("+i.keepalive.join(" sec), retries ")+")":"not set"}`,
    `  Tunnel linestate evaluation ${lineUp(w,d,i)?"up":"down"}`,`  Tunnel source ${src!=null?ip4s(src):"UNKNOWN"}${typeof t.src==="string"?" ("+ifShort(t.src)+")":""}, destination ${t.dst!=null?ip4s(t.dst):"UNKNOWN"}`,
    `   Tunnel Subblocks:`,`      src-track:`,`         ${i.name} source tracking subblock associated with ${typeof t.src==="string"?t.src:"none"}`,
    `  Tunnel protocol/transport ${t.mode==="ipsec"?"IPSEC/IP":t.mode==="mgre"?"multi-GRE/IP":"GRE/IP"}`,`    Key disabled, sequencing disabled`,`    Checksumming of packets disabled`,`  Tunnel TTL 255, Fast tunneling enabled`,`  Tunnel transport MTU 1476 bytes`,
    `  Tunnel transmit bandwidth 8000 (kbps)`,`  Tunnel receive bandwidth 8000 (kbps)`];
  if(t.prot)L.push(`  Tunnel protection via IPSec (profile "${t.prot}")`);
  if(!t.dst)L.push("  % Tunnel is down: no destination configured");else if(src==null)L.push("  % Tunnel is down: the tunnel source has no IP address or is down");else if(!lineUp(w,d,i))L.push(`  % Tunnel is down: no route to the destination ${ip4s(t.dst)} outside the tunnel`);
  else if(!peer){let why="";for(const P of Object.values(w.devs))for(const T of Object.values(P.ifs))if(T.tun&&T.tun.dst===src){const r=IOS.ipsecWhy(w,d,i,P,T);if(r)why=r;else if((T.tun.mode||"gre")!==(t.mode||"gre"))why="the tunnel modes don't match"}
    L.push(`  % No traffic passes: ${why||"no tunnel at "+ip4s(t.dst)+" points back at "+ip4s(src)}`)}
  L.push(`  Last input 00:00:0${peer?2:9}, output 00:00:01, output hang never`,`     ${peer?18233:0} packets input, ${peer?1622107:0} bytes, 0 no buffer`,`     ${peer?18102:0} packets output, ${peer?1599001:0} bytes, 0 underruns`);return L};
S("interfaces tunnel <n>",(d,a,o)=>{const i=d.ifs["Tunnel"+a[0]];return i?IOS.find(["exec"],["show","interfaces","Tunnel"+a[0]]).c.fn(d,["Tunnel"+a[0]],o):`% Invalid interface Tunnel${a[0]}`});
const tunSas=(w,d)=>Object.values(d.ifs).filter(i=>i.tun&&i.tun.prot).map(i=>({i,src:IOS.tunSrc(w,d,i),peer:IOS.tunPeers(w,d.name,i.name)[0]}));
S("crypto isakmp sa",(d,a,o)=>["IPv4 Crypto ISAKMP SA","dst             src             state          conn-id status",...tunSas(o.x.w,d).map(t=>pad(ip4s(t.i.tun.dst),16)+pad(t.src!=null?ip4s(t.src):"0.0.0.0",16)+pad(t.peer?"QM_IDLE":"MM_NO_STATE",15)+pad(t.peer?"1001":"1002",8)+(t.peer?"ACTIVE":"ACTIVE (deleted)")),"","IPv6 Crypto ISAKMP SA"].join("\n"));
S("crypto ipsec sa",(d,a,o)=>tunSas(o.x.w,d).map(t=>{const P=d.crypto.prof[t.i.tun.prot];const ts=P&&d.crypto.ts[P.ts];const n=t.peer?4218:0;
  return [`\ninterface: ${t.i.name}`,`    Crypto map tag: ${t.i.name}-head-0, local addr ${t.src!=null?ip4s(t.src):"0.0.0.0"}`,``,`   protected vrf: (none)`,`   local  ident (addr/mask/prot/port): (${t.src!=null?ip4s(t.src):"0.0.0.0"}/255.255.255.255/47/0)`,`   remote ident (addr/mask/prot/port): (${ip4s(t.i.tun.dst)}/255.255.255.255/47/0)`,`   current_peer ${ip4s(t.i.tun.dst)} port 500`,
    `     #pkts encaps: ${n}, #pkts encrypt: ${n}, #pkts digest: ${n}`,`     #pkts decaps: ${n}, #pkts decrypt: ${n}, #pkts verify: ${n}`,``,`     local crypto endpt.: ${t.src!=null?ip4s(t.src):"0.0.0.0"}, remote crypto endpt.: ${ip4s(t.i.tun.dst)}`,
    t.peer?`     inbound esp sas:\n      spi: 0x7A1C2B9F(2048666527)\n        transform: ${ts?ts.tf:"?"} ,\n        in use settings ={${ts&&ts.mode==="transport"?"Transport":"Tunnel"}, }`:`     inbound esp sas:\n     outbound esp sas:\n     (no security associations: phase 1 or phase 2 did not complete)`].join("\n")}).join("\n")||"There are no IPsec SAs");
S("crypto session",(d,a,o)=>["Crypto session current status","",...tunSas(o.x.w,d).map(t=>`Interface: ${t.i.name}\nSession status: ${t.peer?"UP-ACTIVE":"DOWN"}\nPeer: ${ip4s(t.i.tun.dst)} port 500\n  IKEv1 SA: local ${t.src!=null?ip4s(t.src):"0.0.0.0"}/500 remote ${ip4s(t.i.tun.dst)}/500 ${t.peer?"Active":"Inactive"}\n  IPSEC FLOW: permit 47 host ${t.src!=null?ip4s(t.src):"0.0.0.0"} host ${ip4s(t.i.tun.dst)}\n        Active SAs: ${t.peer?2:0}, origin: crypto map\n`)].join("\n"));
S("crypto isakmp policy",(d)=>Object.entries(d.crypto.isakmp).map(([n,p])=>`\nGlobal IKE policy\nProtection suite of priority ${n}\n\tencryption algorithm:\t${p.enc.startsWith("aes")?"AES - Advanced Encryption Standard ("+(p.enc.split(" ")[1]||128)+" bit keys).":p.enc==="3des"?"Three key triple DES":"DES - Data Encryption Standard (56 bit keys)."}\n\thash algorithm:\t\t${p.hash==="sha"?"Secure Hash Standard":p.hash.toUpperCase()}\n\tauthentication method:\t${p.auth==="pre-share"?"Pre-Shared Key":"Rivest-Shamir-Adleman Signature"}\n\tDiffie-Hellman group:\t#${p.group}\n\tlifetime:\t\t${p.life} seconds, no volume limit`).join("\n"));

/* ---------- BGP ---------- */
const bgpHdr=(w,d)=>`BGP router identifier ${ip4s(IOS.bgpRid(w,d))}, local AS number ${d.bgp.asn}`;
S("ip bgp summary",(d,a,o)=>{const w=o.x.w;if(!d.bgp)return "% BGP not active";const T=IOS.bgpTables(w);const M=T.tables?.get(d.name)||new Map();const P=IOS.bgpPeers(w,d);
  const L=[bgpHdr(w,d),`BGP table version is ${M.size+1}, main routing table version ${M.size+1}`,`${M.size} network entries using ${M.size*152} bytes of memory`,"",`Neighbor        V           AS MsgRcvd MsgSent   TblVer  InQ OutQ Up/Down  State/PfxRcd`];
  P.forEach(p=>{const rcv=[...M.values()].flat().filter(x=>x.from===p.nip).length;L.push(pad(ip4s(p.nip),16)+"4"+rpad(p.nb.ras??"?",13)+rpad(p.state==="Established"?27:0,8)+rpad(p.state==="Established"?29:1,8)+rpad(M.size+1,9)+rpad(0,5)+rpad(0,5)+" "+pad(p.state==="Established"?upt:"never",9)+(p.state==="Established"?rcv:p.state))});
  return L.join("\n")});
S("ip bgp",(d,a,o)=>{const w=o.x.w;if(!d.bgp)return "% BGP not active";const T=IOS.bgpTables(w);const M=T.tables?.get(d.name);if(!M||!M.size)return "";
  const L=[`BGP table version is ${M.size+1}, local router ID is ${ip4s(IOS.bgpRid(w,d))}`,`Status codes: s suppressed, d damped, h history, * valid, > best, i - internal,`,`              r RIB-failure, S Stale, m multipath, b backup-path, f RT-Filter,`,`              x best-external, a additional-path, c RIB-compressed,`,`Origin codes: i - IGP, e - EGP, ? - incomplete`,`RPKI validation codes: V valid, I invalid, N Not found`,"",`     Network          Next Hop            Metric LocPrf Weight Path`];
  [...M.entries()].sort((x,y)=>{const [a1,l1]=x[0].split("/").map(BigInt),[a2,l2]=y[0].split("/").map(BigInt);return a1<a2?-1:a1>a2?1:Number(l1-l2)}).forEach(([k,paths])=>{
    const sorted=paths.slice().sort((p,q)=>(q.best?1:0)-(p.best?1:0));
    sorted.forEach((p,j)=>{const st=(p.valid?"*":" ")+(p.best?">":" ")+(p.src==="ibgp"?"i":" ");const net=j===0?pad(ip4s(p.n)+(p.len!==(Number(p.n>>24n)<128?8:Number(p.n>>24n)<192?16:24)?"/"+p.len:""),17):pad("",17);
      L.push(` ${st} ${net}${pad(p.nh===0n?"0.0.0.0":ip4s(p.nh),20)}${rpad(p.med||0,6)}${rpad(p.src==="ibgp"||p.lp!==100?p.lp:"",7)}${rpad(p.weight,7)} ${[...p.path,p.origin].join(" ")}`)})});
  return L.join("\n")});
S("ip bgp neighbors",(d,a,o)=>{const w=o.x.w;if(!d.bgp)return "% BGP not active";return IOS.bgpPeers(w,d).map(p=>nbrOut(w,d,p)).join("\n\n")});
S("ip bgp neighbors <ip>",(d,a,o)=>{const w=o.x.w;if(!d.bgp)return "% BGP not active";const p=IOS.bgpPeers(w,d).find(x=>x.nip===a[0]);return p?nbrOut(w,d,p):`% No such neighbor or address family`});
function nbrOut(w,d,p){return [`BGP neighbor is ${ip4s(p.nip)},  remote AS ${p.nb.ras}, ${p.ebgp?"external":"internal"} link`+(p.nb.desc?`\n Description: ${p.nb.desc}`:""),`  BGP version 4, remote router ID ${p.P&&p.state==="Established"?ip4s(IOS.bgpRid(w,p.P)):"0.0.0.0"}`,`  BGP state = ${p.state}${p.state==="Established"?", up for "+upt:""}`,
  p.state!=="Established"?`  Last reset never, due to: ${p.why}`:`  Last read 00:00:21, last write 00:00:17, hold time is 180, keepalive interval is 60 seconds`,`  Neighbor sessions:`,`    1 active, is not multisession capable (disabled)`,
  ...(p.nb.rmIn?[`  Route map for incoming advertisements is ${p.nb.rmIn}`]:[]),...(p.nb.rmOut?[`  Route map for outgoing advertisements is ${p.nb.rmOut}`]:[]),
  `  Local host: ${p.pip!=null?ip4s(p.pip):"0.0.0.0"}, Local port: 179`,`  Foreign host: ${ip4s(p.nip)}, Foreign port: ${p.state==="Established"?"36211":"0"}`].join("\n")}
IOS.protoExtra=(w,d)=>{if(!d.bgp)return [];const P=IOS.bgpPeers(w,d);return ["",`Routing Protocol is "bgp ${d.bgp.asn}"`,`  Outgoing update filter list for all interfaces is not set`,`  Incoming update filter list for all interfaces is not set`,`  IGP synchronization is disabled`,`  Automatic route summarization is disabled`,`  Neighbor(s):`,`    Address          FiltIn FiltOut DistIn DistOut Weight RouteMap`,...P.map(p=>"    "+pad(ip4s(p.nip),56)+(p.nb.rmIn||"")),`  Maximum path: 1`,`  Routing Information Sources:`,`    Gateway         Distance      Last Update`,...P.filter(p=>p.state==="Established").map(p=>"    "+pad(ip4s(p.nip),16)+pad(p.ebgp?"20":"200",14)+upt),`  Distance: external 20 internal 200 local 200`]};

/* ---------- OSPF database (summary view) ---------- */
S("ip ospf database",(d,a,o)=>{const w=o.x.w;if(!d.ospf)return "";const rid=IOS.ospfRid(w,d,false);const L=[``,`            OSPF Router with ID (${rid!=null?ip4s(rid):"0.0.0.0"}) (Process ID ${d.ospf.pid})`];
  const R=Object.values(w.devs).filter(x=>x.ospf&&IOS.ospfRid(w,x,false)!=null);
  [...IOS.ospfAreas(w,d,false)].sort((a,b)=>a-b).forEach(ar=>{const inA=R.filter(x=>IOS.ospfAreas(w,x,false).has(ar)&&(x===d||IOS.spf(w,d,false).dist.has(x.name)));
    L.push("",`                Router Link States (Area ${ar})`,"","Link ID         ADV Router      Age         Seq#       Checksum Link count");
    inA.forEach(x=>{const r=ip4s(IOS.ospfRid(w,x,false));L.push(pad(r,16)+pad(r,16)+pad("412",12)+"0x80000004 0x00A1B2 "+Object.values(x.ifs).filter(i=>String(IOS.ospfIfCfg(w,x,i,false)?.area)===ar).length)});
    const abrs=inA.filter(x=>IOS.isAbr(w,x,false));
    if(abrs.length&&!(d.ospf.stubs?.[ar]?.nosum||abrs.some(x=>x.ospf.stubs?.[ar]?.nosum))){const sums=new Set();IOS.ospfRoutes(w,d,false).filter(r=>r.code==="O IA").forEach(r=>sums.add(ip4s(r.n)));
      if(d.ospf&&IOS.isAbr(w,d,false))rib(w,d,4).filter(r=>r.code==="O"&&!r.discard).forEach(()=>{});
      if(sums.size){L.push("",`                Summary Net Link States (Area ${ar})`,"","Link ID         ADV Router      Age         Seq#       Checksum");[...sums].forEach(s=>L.push(pad(s,16)+pad(ip4s(IOS.ospfRid(w,abrs[0],false)),16)+pad("388",12)+"0x80000002 0x00C4D1"))}}});
  const ext=IOS.ospfRoutes(w,d,false).filter(r=>r.code==="O E2");if(ext.length){L.push("",`                Type-5 AS External Link States`,"","Link ID         ADV Router      Age         Seq#       Checksum Tag");ext.forEach(r=>L.push(pad(ip4s(r.n),16)+pad("(ASBR)",16)+pad("301",12)+"0x80000001 0x00E77A 0"))}
  return L.join("\n")});

/* ---------- prefix lists, route maps, PBR ---------- */
S("ip prefix-list",(d)=>Object.entries(d.plists).map(([n,L])=>`ip prefix-list ${n}: ${L.length} entries\n`+L.map(e=>`   seq ${e.seq} ${e.act} ${ip4s(e.n)}/${e.len}${e.ge!=null?" ge "+e.ge:""}${e.le!=null?" le "+e.le:""}`).join("\n")).join("\n"));
const rmText=(n,e)=>[`route-map ${n}, ${e.act}, sequence ${e.seq}`,`  Match clauses:`,...e.match.map(m=>m.t==="pl"?`    ip address prefix-lists: ${m.v} `:`    ip address (access-lists): ${m.v} `),`  Set clauses:`,...(e.set.lp!=null?[`    local-preference ${e.set.lp}`]:[]),...(e.set.weight!=null?[`    weight ${e.set.weight}`]:[]),...(e.set.med!=null?[`    metric ${e.set.med}`]:[]),...(e.set.prepend?[`    as-path prepend ${e.set.prepend.join(" ")}`]:[]),...(e.set.nh?[`    ip next-hop ${e.set.nh.map(ip4s).join(" ")}`]:[]),...(e.set.oif?[`    interface ${e.set.oif}`]:[]),`  Policy routing matches: 0 packets, 0 bytes`].join("\n");
S("route-map",(d)=>Object.entries(d.rmaps).map(([n,L])=>L.map(e=>rmText(n,e)).join("\n")).join("\n"));
S("route-map <w>",(d,a)=>d.rmaps[a[0]]?d.rmaps[a[0]].map(e=>rmText(a[0],e)).join("\n"):"%route-map "+a[0]+" not found");
S("ip policy",(d)=>["Interface      Route map",...Object.values(d.ifs).filter(i=>i.policy).map(i=>pad(ifShort(i.name),15)+i.policy+(d.rmaps[i.policy]?"":"  (route-map not defined)"))].join("\n"));

/* ---------- tracking and IP SLA ---------- */
const trkText=(w,d,k,t)=>{const up=IOS.trackUp(w,d,+k);const what=t.type==="if"?`Interface ${t.if} ${t.mode}`:t.type==="sla"?`IP SLA ${t.sla} ${t.mode}`:`IP route ${ip4s(t.n)} ${lenMask(t.len)} reachability`;
  const users=[];Object.values(d.ifs).forEach(i=>{Object.entries(i.hsrp).forEach(([g,c])=>{if((c.track||[]).some(x=>x.obj===+k))users.push(`HSRP ${ifShort(i.name)} ${g}`)});Object.entries(i.vrrp).forEach(([g,c])=>{if((c.track||[]).some(x=>x.obj===+k))users.push(`VRRP ${ifShort(i.name)} ${g}`)})});
  d.routes.forEach(r=>{if(r.track===+k)users.push("STATIC-IP-ROUTING")});
  return [`Track ${k}`,`  ${what}`,`  ${t.type==="sla"?t.mode==="state"?"State is "+(up?"Up":"Down"):"Reachability is "+(up?"Up":"Down"):t.type==="if"&&t.mode==="line-protocol"?"Line protocol is "+(up?"Up":"Down"):"IP routing is "+(up?"Up":"Down")}`,`    1 change, last change ${upt}`,...(t.delay?[`  Delay ${t.delay}`]:[]),...(users.length?[`  Tracked by:`,...users.map(u=>"    "+u)]:[])].join("\n")};
S("track",(d,a,o)=>Object.entries(d.tracks).map(([k,t])=>trkText(o.x.w,d,k,t)).join("\n"));
S("track <n>",(d,a,o)=>d.tracks[a[0]]?trkText(o.x.w,d,a[0],d.tracks[a[0]]):`%Track object ${a[0]} does not exist`);
S("track brief",(d,a,o)=>["Track Type        Instance                   Parameter        State Last Change",...Object.entries(d.tracks).map(([k,t])=>pad(k,6)+pad(t.type==="if"?"interface":t.type==="sla"?"ip sla":"ip route",13)+pad(t.type==="if"?ifShort(t.if):t.type==="sla"?t.sla:ip4s(t.n)+"/"+t.len,27)+pad(t.type==="sla"?t.mode:t.type==="if"?"line-protocol":"reachability",17)+pad(IOS.trackUp(o.x.w,d,+k)?"Up":"Down",6)+upt)].join("\n"));
const slaStat=(w,d,k,s)=>{const ok=IOS.slaOk(w,d,+k);return [`IPSLA operation id: ${k}`,`        Latest RTT: ${ok?"2 milliseconds":"NoConnection/Busy/Timeout"}`,`Latest operation start time: ${s.sched?"10:41:07 UTC "+new Date().toUTCString().slice(0,16):"Never"}`,`Latest operation return code: ${!s.sched?"Unknown":ok?"OK":"Timeout"}`,`Number of successes: ${s.sched?(ok?14:2):0}`,`Number of failures: ${s.sched?(ok?0:12):0}`,`Operation time to live: ${s.sched?"Forever":"0"}`].join("\n")};
S("ip sla statistics",(d,a,o)=>"IPSLAs Latest Operation Statistics\n\n"+Object.entries(d.slas).map(([k,s])=>slaStat(o.x.w,d,k,s)).join("\n\n"));
S("ip sla statistics <n>",(d,a,o)=>d.slas[a[0]]?"IPSLAs Latest Operation Statistics\n\n"+slaStat(o.x.w,d,a[0],d.slas[a[0]]):"");
S("ip sla summary",(d,a,o)=>["IPSLAs Latest Operation Summary","Codes: * active, ^ inactive, ~ pending","","ID           Type        Destination       Stats       Return      Last","                                             (ms)        Code        Run","-----------------------------------------------------------------------",...Object.entries(d.slas).map(([k,s])=>{const ok=IOS.slaOk(o.x.w,d,+k);return (s.sched?"*":"^")+pad(k,12)+pad(s.type||"-",12)+pad(s.dst!=null?ip4s(s.dst):"-",18)+pad(ok?"RTT=2":"-",12)+pad(!s.sched?"Unknown":ok?"OK":"Timeout",12)+"3 seconds ago"})].join("\n"));
S("ip sla configuration",(d)=>Object.entries(d.slas).map(([k,s])=>[`IP SLAs Infrastructure Engine-III`,`Entry number: ${k}`,`Type of operation to perform: ${s.type||"none"}`,`Target address/Source interface: ${s.dst!=null?ip4s(s.dst):"0.0.0.0"}/${s.srcIf?s.srcIf:"none"}`,`Operation frequency (seconds): ${s.freq}`,`Schedule:`,`   Operation frequency (seconds): ${s.freq}  (not considered if randomly scheduled)`,`   Next Scheduled Start Time: ${s.sched?"Start Time already passed":"Pending trigger"}`,`   Life (seconds): ${s.sched?"Forever":"3600"}`].join("\n")).join("\n\n"));
S("standby",(d,a,o)=>{const G=IOS.fhrp(o.x.w,"hsrp");const L=[];Object.values(G).forEach(M=>M.filter(x=>x.d===d).forEach(x=>{L.push(`${x.i.name} - Group ${x.g}${d.ifs[x.i.name].hsrpV===2?" (version 2)":""}`,`  State is ${x.state}`,`  Virtual IP address is ${x.vip!=null?ip4s(x.vip):"unknown"}`,`  Hello time ${x.c.timers?x.c.timers[0]:3} sec, hold time ${x.c.timers?x.c.timers[1]:10} sec`,`  Preemption ${x.c.preempt?"enabled":"disabled"}`,`  Active router is ${x.active?(x.active===x?"local":ip4s(x.active.i.ip)+", priority "+x.active.pri):"unknown"}`,`  Standby router is ${x.standby?(x.standby===x?"local":ip4s(x.standby.i.ip)+", priority "+x.standby.pri):"unknown"}`,
  `  Priority ${x.pri} (${x.pri===x.cfgPri?(x.c.pri!=null?"configured "+x.c.pri:"default 100"):"configured "+x.cfgPri})`,...(x.c.track||[]).map(t=>`    Track object ${t.obj} state ${IOS.trackUp(o.x.w,d,t.obj)?"Up":"Down"} decrement ${t.dec}`),...(x.c.auth?["  Authentication MD5, key-string"]:[]))}));return L.join("\n")});
S("vrrp",(d,a,o)=>{const G=IOS.fhrp(o.x.w,"vrrp");const L=[];Object.values(G).forEach(M=>M.filter(x=>x.d===d).forEach(x=>{L.push(`${x.i.name} - Group ${x.g} - Address-Family IPv4`,`  State is ${x.state.toUpperCase()}`,`  Virtual IP address is ${x.vip!=null?ip4s(x.vip):"unknown"}`,`  Advertisement interval is 1000 msec`,`  Preemption ${x.preempt?"enabled":"disabled"}`,`  Priority is ${x.pri}${x.pri!==x.cfgPri?` (configured ${x.cfgPri})`:""}`,...(x.c.track||[]).map(t=>`    Track object ${t.obj} state ${IOS.trackUp(o.x.w,d,t.obj)?"Up":"Down"} decrement ${t.dec}`),`  Master Router is ${x.active?(x.active===x?ip4s(x.i.ip)+" (local)":ip4s(x.active.i.ip)):"unknown"}, priority is ${x.active?x.active.pri:"0"}`)}));return L.join("\n")});

/* ---------- MST ---------- */
IOS.mstCfgOut=(d,kind)=>{const L=[`${kind?kind+" ":""}MST configuration`,`Name      [${d.mst.name}]`,`Revision  ${d.mst.rev}     Instances configured ${Object.keys(d.mst.inst).length+1}`,"",`Instance  Vlans mapped`,`--------  ---------------------------------------------------------------------`];
  const used=new Set(Object.values(d.mst.inst).flat());const rest=[];for(let v=1;v<=4094;v++)if(!used.has(v))rest.push(v);
  const rng=L2=>{const out=[];let s=null,p=null;L2.forEach(v=>{if(s===null){s=p=v;return}if(v===p+1){p=v;return}out.push(s===p?s:s+"-"+p);s=p=v});if(s!==null)out.push(s===p?s:s+"-"+p);return out.join(",")};
  L.push(pad("0",10)+rng(rest));Object.entries(d.mst.inst).forEach(([k,V])=>L.push(pad(k,10)+rng(V)));L.push("-------------------------------------------------------------------------------");return L.join("\n")};
S("spanning-tree mst configuration",(d)=>d.kind==="router"?INV:IOS.mstCfgOut(d,""));
const mstOut=(w,d,only)=>{if(d.kind==="router")return INV;if(d.stp.mode!=="mst")return "% Switch is not in mst mode";const insts=[0,...Object.keys(d.mst.inst).map(Number)].filter(k=>only==null||k===only);
  return insts.map(k=>{const vl=k===0?Object.keys(d.vlans).map(Number).filter(v=>IOS.mstInst(d,v)===0):d.mst.inst[k];const v=vl.find(x=>d.vlans[x])??1;const {T,out:P}=IOS.stpPorts(w,d,v);if(!T)return "";
    const me=IOS.bid(d,v),rt=IOS.bid(T.root,v);const rp=T.rp.get(d.name);
    return [``,`##### MST${k}    vlans mapped:   ${vl.join(",")||"none"}`,`Bridge        address ${me.mac.slice(0,14)}  priority      ${me.p} (${me.p-k} sysid ${k})`,T.root===d?`Root          this switch for ${k===0?"the CIST":"MST"+k}`:`Root          address ${rt.mac.slice(0,14)}  priority      ${rt.p} (${rt.p-k} sysid ${k})\n              port    ${rp?ifShort(rp.i):"none"}           cost          ${T.cost.get(d.name)*5000}     rem hops 19`,`Operational   hello time 2 , forward delay 15, max age 20, txholdcount 6`,`Configured    hello time 2 , forward delay 15, max age 20, max hops    20`,``,
      `Interface        Role Sts Cost      Prio.Nbr Type`,`---------------- ---- --- --------- -------- --------------------------------`,...P.map(p=>pad(ifShort(p.i.name),17)+pad(p.role,5)+pad(p.st,4)+pad(p.cost*5000,10)+pad("128."+(Object.keys(d.ifs).indexOf(p.i.name)+1),9)+(p.edge?"P2p Edge":"P2p")+(p.rootInc?" *ROOT_Inc":""))].join("\n")}).join("\n")};
S("spanning-tree mst",(d,a,o)=>mstOut(o.x.w,d));S("spanning-tree mst <n>",(d,a,o)=>mstOut(o.x.w,d,a[0]));
S("spanning-tree inconsistentports",(d,a,o)=>{if(d.kind==="router")return INV;const L=["Name                 Interface                Inconsistency","-------------------- ------------------------ ------------------"];let n=0;
  Object.keys(d.vlans).map(Number).forEach(v=>{const {out:P}=IOS.stpPorts(o.x.w,d,v);P.filter(p=>p.rootInc).forEach(p=>{n++;L.push(pad(d.stp.mode==="mst"?"MST"+IOS.mstInst(d,v):"VLAN"+String(v).padStart(4,"0"),21)+pad(p.i.name,25)+"Root Inconsistent")})});
  L.push("",`Number of inconsistent ports (segments) in the system : ${n}`);return L.join("\n")});

/* ---------- NTP ---------- */
S("ntp associations",(d,a,o)=>{const w=o.x.w;const st=IOS.ntpState(w,d);const L=["","  address         ref clock       st   when   poll reach  delay  offset   disp"];
  if(d.ntpx.master!=null)L.push(`*~127.127.1.1     .LOCL.          ${pad(d.ntpx.master-1,5)}${pad("5",7)}16     377  0.000   0.000  0.240`);
  d.ntp.forEach(n=>{const t=IOS.deviceWithIp(w,n);const sel=st.synced&&st.peer===ip4s(n);const ts=t?IOS.ntpState(w,t.d,1):{synced:false};const reach=IOS.ping(w,{dev:d},n,4,{proto:"udp",port:123}).ok;
    L.push(`${sel?"*":" "}~${pad(ip4s(n),16)}${pad(reach&&ts.synced?ts.ref||".LOCL.":".INIT.",16)}${pad(reach&&ts.synced?ts.stratum:16,5)}${pad(reach?"41":"-",7)}${pad("64",7)}${pad(reach?(sel?"377":"17"):"0",6)}${reach?" 1.012  -0.204  0.947":" 0.000   0.000 15937."}`)});
  L.push(" * sys.peer, # selected, + candidate, - outlyer, x falseticker, ~ configured");return L.join("\n")});
S("ntp status",(d,a,o)=>{const s=IOS.ntpState(o.x.w,d);return s.synced?`Clock is synchronized, stratum ${s.stratum}, reference is ${s.ref}\nnominal freq is 250.0000 Hz, actual freq is 250.0000 Hz, precision is 2**10\nntp uptime is 120000 (1/100 of seconds), resolution is 4000\nreference time is E9F1A2B3.1C28F5C3 (10:41:07.110 UTC)\nclock offset is -0.2040 msec, root delay is 1.01 msec\nroot dispersion is 3.54 msec, peer dispersion is 0.94 msec\nloopfilter state is 'CTRL' (Normal Controlled Loop), drift is 0.000000000 s/s\nsystem poll interval is 64, last update was 41 sec ago.`:`Clock is unsynchronized, stratum 16, no reference clock\nnominal freq is 250.0000 Hz, actual freq is 250.0000 Hz, precision is 2**10\nntp uptime is 120000 (1/100 of seconds), resolution is 4000\nreference time is 00000000.00000000 (00:00:00.000 UTC Mon Jan 1 1900)\nclock offset is 0.0000 msec, root delay is 0.00 msec\nroot dispersion is 0.00 msec, peer dispersion is 0.00 msec\nloopfilter state is 'FSET' (Drift set from file), drift is 0.000000000 s/s\nsystem poll interval is 8, never updated.`});

/* ---------- QoS and CoPP ---------- */
const pmText=(d,name,ind)=>{const P=d.pmaps[name];if(!P)return "";const sp=" ".repeat(ind||0);const L=[`${sp}  Policy Map ${name}`];
  P.classes.forEach(c=>{L.push(`${sp}    Class ${c.cls}`);const A=c.act;
    if(A.priority)L.push(`${sp}      priority${A.priority.pct!=null?" "+A.priority.pct+" (%)":A.priority.kbps!=null?" "+A.priority.kbps+" (kbps)":""}${A.priority.level?" level "+A.priority.level:""}`);
    if(A.bandwidth)L.push(`${sp}      bandwidth ${A.bandwidth.rem!=null?"remaining "+A.bandwidth.rem+" (%)":A.bandwidth.pct!=null?A.bandwidth.pct+" (%)":A.bandwidth.kbps+" (kbps)"}`);
    if(A.shape)L.push(`${sp}      Average Rate Traffic Shaping`,`${sp}      cir ${A.shape.pct!=null?A.shape.pct+"%":A.shape.avg} `);
    if(A.police)L.push(`${sp}      police ${A.police.pps?"rate "+A.police.cir+" pps":"cir "+A.police.cir+" bc "+(A.police.bc||Math.round(A.police.cir/32))}`,`${sp}        conform-action ${A.police.conform}${A.police.conformV?" "+A.police.conformV:""}`,`${sp}        exceed-action ${A.police.exceed}${A.police.exceedV?" "+A.police.exceedV:""}`);
    if(A.set)L.push(`${sp}      set dscp ${A.set.dscp}`);if(A.fq)L.push(`${sp}      fair-queue`);if(A.drop)L.push(`${sp}      drop`);if(A.wred)L.push(`${sp}      random-detect ${A.wred}`);
    if(A.child){L.push(`${sp}      service-policy ${A.child}`)}});return L.join("\n")};
S("policy-map",(d)=>Object.keys(d.pmaps).map(n=>pmText(d,n)).join("\n\n"));
S("policy-map <w>",(d,a)=>d.pmaps[a[0]]?pmText(d,a[0]):`Policy Map ${a[0]} not configured`);
const cmMatch=(d,name)=>{if(name==="class-default")return "any";const M=d.cmaps[name];return M?M.matches.map(m=>m.t+(m.v?" "+m.v:"")).join(M.any?"  OR  ":"  AND  ")||"(nothing)":"(class-map missing)"};
const pmIf=(d,name,dir,head)=>{const P=d.pmaps[name];if(!P)return "";const L=[head,"",`  Service-policy ${dir}: ${name}`];
  P.classes.concat(P.classes.some(c=>c.cls==="class-default")?[]:[{cls:"class-default",act:{}}]).forEach(c=>{const M=d.cmaps[c.cls];L.push("",`    Class-map: ${c.cls} (${c.cls==="class-default"?"match-any":M&&M.any?"match-any":"match-all"})`,`      0 packets, 0 bytes`,`      5 minute offered rate 0000 bps, drop rate 0000 bps`,`      Match: ${cmMatch(d,c.cls)}`);
    const A=c.act;if(A.priority)L.push(`      Priority: ${A.priority.pct!=null?A.priority.pct+"% ":A.priority.kbps!=null?A.priority.kbps+" kbps":"Strict"}, burst bytes 1500, b/w exceed drops: 0`);if(A.bandwidth)L.push(`      Queueing`,`      queue limit 64 packets`,`      bandwidth ${A.bandwidth.rem!=null?"remaining "+A.bandwidth.rem+"%":A.bandwidth.pct!=null?A.bandwidth.pct+"%":A.bandwidth.kbps+" kbps"}`);
    if(A.police)L.push(`      police:`,`          ${A.police.pps?"rate "+A.police.cir+" pps":"cir "+A.police.cir+" bps, bc "+(A.police.bc||Math.round(A.police.cir/32))+" bytes"}`,`        conformed 0 packets, 0 bytes; actions:`,`          ${A.police.conform}`,`        exceeded 0 packets, 0 bytes; actions:`,`          ${A.police.exceed}`);
    if(A.set)L.push(`      QoS Set`,`        dscp ${A.set.dscp}`,`          Marker statistics: Disabled`);if(A.drop)L.push(`      drop`);if(A.shape)L.push(`      Queueing`,`      shape (average) cir ${A.shape.pct!=null?A.shape.pct+"%":A.shape.avg}`)});
  return L.join("\n")};
S("policy-map interface <if>",(d,a)=>{const i=d.ifs[a[0]];if(!i)return INV;return [i.svc.in?pmIf(d,i.svc.in,"input",` ${i.name} `):"",i.svc.out?pmIf(d,i.svc.out,"output",` ${i.name} `):""].filter(Boolean).join("\n\n")||""});
S("policy-map interface",(d)=>Object.values(d.ifs).filter(i=>i.svc.in||i.svc.out).map(i=>[i.svc.in?pmIf(d,i.svc.in,"input",` ${i.name} `):"",i.svc.out?pmIf(d,i.svc.out,"output",` ${i.name} `):""].filter(Boolean).join("\n\n")).join("\n\n"));
S("policy-map control-plane",(d)=>d.cpSvc?pmIf(d,d.cpSvc,"input"," Control Plane "):"");
S("class-map",(d)=>Object.entries(d.cmaps).map(([n,M])=>` Class Map ${M.any?"match-any":"match-all"} ${n} (id 1)\n`+M.matches.map(m=>`   Match ${m.t}${m.v?" "+m.v:""}`).join("\n")).join("\n\n"));

/* ---------- Flexible NetFlow ---------- */
const F=d=>d.fnf;
S("flow record",(d)=>Object.entries(F(d).rec).map(([n,R])=>`flow record ${n}:\n  Description:        User defined\n  No. of users:       ${Object.values(F(d).mon).filter(m=>m.rec===n).length}\n  Total field space:  ${12+R.match.length*4} bytes\n  Fields:\n${R.match.map(m=>"    match "+m).join("\n")}\n${R.collect.map(m=>"    collect "+m).join("\n")}`).join("\n\n"));
S("flow exporter",(d,a,o)=>Object.entries(F(d).exp).map(([n,E])=>{const r=E.dst!=null&&IOS.ping(o.x.w,{dev:d},E.dst,4,{proto:"udp",port:E.port,src:E.src&&d.ifs[E.src]?IOS.ifAddr(o.x.w,d,d.ifs[E.src])?.n:undefined}).ok;
  return `Flow Exporter ${n}:\n  Description:              User defined\n  Export protocol:          ${E.proto==="ipfix"?"IPFIX (Version 10)":E.proto==="netflow-v5"?"NetFlow Version 5":"NetFlow Version 9"}\n  Transport Configuration:\n    Destination IP address: ${E.dst!=null?ip4s(E.dst):"Not configured"}\n    Source IP address:      ${E.src&&d.ifs[E.src]&&d.ifs[E.src].ip!==null?ip4s(d.ifs[E.src].ip):"Not configured"}\n    Source Interface:       ${E.src||"Not configured"}\n    Transport Protocol:     UDP\n    Destination Port:       ${E.port}\n    Source Port:            53214\n    DSCP:                   0x0\n    TTL:                    255\n    Output Features:        Not Used\n  Export status:            ${E.dst==null?"No destination configured":r?"Exporting (collector reachable)":"Collector unreachable"}`}).join("\n\n"));
S("flow monitor",(d)=>Object.entries(F(d).mon).map(([n,M])=>`Flow Monitor ${n}:\n  Description:       User defined\n  Flow Record:       ${M.rec||"not configured"}\n  Flow Exporter:     ${M.exp.join(", ")||"not configured"}\n  Cache:\n    Type:                 normal (Platform cache)\n    Status:               ${Object.values(d.ifs).some(i=>i.flowMon.in===n||i.flowMon.out===n)?"allocated":"not allocated"}\n    Size:                 200000 entries\n    Inactive Timeout:     ${M.inactive} secs\n    Active Timeout:       ${M.active} secs`).join("\n\n"));
S("flow monitor <w> cache",(d,a,o)=>{const M=F(d).mon[a[0]];if(!M)return `% Flow Monitor ${a[0]} does not exist`;const on=Object.values(d.ifs).filter(i=>i.flowMon.in===a[0]||i.flowMon.out===a[0]);if(!on.length)return `  Cache type:                               Normal (Platform cache)\n  Cache size:                               200000\n  Current entries:                          0\n\n  (the monitor isn't applied to any interface, so it sees no traffic)`;
  const R=F(d).rec[M.rec];const flows=(o.x.w.traffic||[]).filter(t=>t.dev===d.name||!t.dev);
  return `  Cache type:                               Normal (Platform cache)\n  Cache size:                               200000\n  Current entries:                          ${flows.length||3}\n\nIPV4 SRC ADDR    IPV4 DST ADDR    TRNS SRC PORT  TRNS DST PORT  IP PROT  bytes long  pkts long\n===============  ===============  =============  =============  =======  ==========  =========\n`+(flows.length?flows:[{src:"10.1.10.21",dst:"10.9.0.5",sp:51522,dp:443,p:6,b:182211,n:212},{src:"10.1.10.35",dst:"10.9.0.53",sp:61001,dp:53,p:17,b:840,n:6},{src:"10.1.20.9",dst:"10.9.0.80",sp:49233,dp:80,p:6,b:56110,n:71}]).map(f=>pad(f.src,17)+pad(f.dst,17)+pad(R&&!R.match.some(m=>/transport source/.test(m))?"0":f.sp,15)+pad(R&&!R.match.some(m=>/transport destination/.test(m))?"0":f.dp,15)+pad(f.p,9)+pad(f.b,12)+f.n).join("\n")});
S("flow interface",(d)=>Object.values(d.ifs).filter(i=>i.flowMon.in||i.flowMon.out).map(i=>`Interface ${i.name}\n`+[i.flowMon.in?`  FNF:  monitor:         ${i.flowMon.in}\n        direction:       Input\n        traffic(ip):     on`:"",i.flowMon.out?`  FNF:  monitor:         ${i.flowMon.out}\n        direction:       Output\n        traffic(ip):     on`:""].filter(Boolean).join("\n")).join("\n"));

/* ---------- SPAN ---------- */
const monText=(d,k,M)=>{const srcBy=dir=>M.src.filter(s=>s.dir===dir||s.dir==="both").map(s=>ifShort(s.if)).join(",");
  const L=[`Session ${k}`,`---------`,`Type                     : ${M.type==="local"?"Local Session":M.type==="rspan-src"?"Remote Source Session":M.type==="rspan-dst"?"Remote Destination Session":"ERSPAN Source Session"}`];
  if(M.src.length){L.push(`Source Ports             : `);if(srcBy("rx"))L.push(`    RX Only              : ${M.src.filter(s=>s.dir==="rx").map(s=>ifShort(s.if)).join(",")||"None"}`);if(M.src.some(s=>s.dir==="tx"))L.push(`    TX Only              : ${M.src.filter(s=>s.dir==="tx").map(s=>ifShort(s.if)).join(",")}`);if(M.src.some(s=>s.dir==="both"))L.push(`    Both                 : ${M.src.filter(s=>s.dir==="both").map(s=>ifShort(s.if)).join(",")}`)}
  if(M.srcVlan)L.push(`Source VLANs             : `,`    ${M.vdir==="rx"?"RX Only":M.vdir==="tx"?"TX Only":"Both"}                 : ${M.srcVlan}`);
  if(M.srcRemote)L.push(`Source RSPAN VLAN        : ${M.srcRemote}`);if(M.dst)L.push(`Destination Ports        : ${ifShort(M.dst)}`,`    Encapsulation        : ${M.repl?"Replicate":"Native"}`,`          Ingress        : Disabled`);if(M.dstVlan)L.push(`Dest RSPAN VLAN          : ${M.dstVlan}`);
  if(M.type==="erspan-src")L.push(`Status                   : ${M.er.shut?"Admin Disabled":"Admin Enabled"}`,`Destination IP Address   : ${M.er.ip!=null?ip4s(M.er.ip):"not set"}`,`Destination ERSPAN ID    : ${M.er.id??"not set"}`,`Origin IP Address        : ${M.er.origin!=null?ip4s(M.er.origin):"not set"}`);
  if(M.type==="local"&&(!M.dst||(!M.src.length&&!M.srcVlan)))L.push(`(incomplete session: it needs both a source and a destination)`);return L.join("\n")};
S("monitor session <n>",(d,a)=>d.mon[a[0]]?monText(d,a[0],d.mon[a[0]]):`No SPAN configuration exists for session ${a[0]}`);
S("monitor session all",(d)=>Object.entries(d.mon).map(([k,M])=>monText(d,k,M)).join("\n\n"));
S("monitor",(d)=>Object.entries(d.mon).map(([k,M])=>monText(d,k,M)).join("\n\n"));

/* ---------- EEM, debugging, misc ---------- */
S("event manager policy registered",(d)=>{const L=["No.  Class     Type    Event Type          Trap  Time Registered           Name"];let n=1;Object.entries(d.eem).forEach(([k,A])=>{if(!A.ev)return;L.push(`${pad(n++,5)}applet    user    ${pad(A.ev.t==="none"?"none":A.ev.t==="syslog"?"syslog":A.ev.t==="track"?"track":A.ev.t,20)}Off   ${new Date().toUTCString().slice(0,25)}  ${k}`);
  L.push(A.ev.t==="syslog"?` pattern {${A.ev.pat}}`:A.ev.t==="track"?` track ${A.ev.id} state ${A.ev.state}`:` `);[...A.acts].forEach(x=>L.push(` action ${x.lbl} ${x.t==="cli"?"cli command \""+x.cmd+"\"":x.t==="syslog"?"syslog msg \""+x.msg+"\"":x.t}`))});return L.join("\n")});
S("event manager history events",(d)=>["No.  Job Id Proc Status       Time of Event            Event Type   Name",...Object.entries(d.eem).filter(([k,A])=>A.runs).map(([k,A],i)=>`${pad(i+1,5)}${pad(i+1,7)}Actv success      ${new Date().toUTCString().slice(5,25)} ${pad(A.ev?.t||"none",13)}applet: ${k}`)].join("\n"));
S("debugging",(d)=>{const L=[];const c=d.dbg.filter(x=>x.startsWith("cond"));d.dbg.filter(x=>!x.startsWith("cond")).forEach(x=>L.push(`${x.split(" ").slice(0,2).join(" ").toUpperCase()}:\n  ${x} debugging is on`));
  if(c.length){L.push("","Condition 1 to "+c.length+":");c.forEach((x,k)=>L.push(`Condition ${k+1}: ${x.startsWith("cond:")?"interface "+x.slice(5):"ip "+x.slice(7)} (1 flags triggered)`))}return L.join("\n")||""});
S("debug condition",(d)=>d.dbg.filter(x=>x.startsWith("cond")).map((x,k)=>`Condition ${k+1}: ${x.startsWith("cond:")?"interface "+x.slice(5):"ip "+x.slice(7)} (1 flags triggered)\n        Flags: ${x.startsWith("cond:")?x.slice(5):x.slice(7)}`).join("\n")||"% No conditions found");
S("ip pim neighbor",(d,a,o)=>{const w=o.x.w;const L=["PIM Neighbor Table","Mode: B - Bidir Capable, DR - Designated Router, N - Default DR Priority,","      P - Proxy Capable, S - State Refresh Capable, G - GenID Capable","Neighbor          Interface                Uptime/Expires    Ver   DR","Address                                                            Prio/Mode"];
  Object.values(d.ifs).forEach(i=>{if(!i.pim||!lineUp(w,d,i))return;IOS.peersOf(w,d.name,i.name).forEach(([pd,pi])=>{const P=w.devs[pd],PI=P&&P.ifs[pi];if(PI&&PI.pim&&PI.pim!=="passive"&&i.pim!=="passive"&&lineUp(w,P,PI)&&PI.ip!==null&&P.mcast)L.push(pad(ip4s(PI.ip),18)+pad(i.name,25)+pad(upt+"/00:01:35",18)+"v2    1 / "+(PI.ip>i.ip?"DR S P G":"S P G"))})});return L.join("\n")});
S("ip pim rp mapping",(d)=>d.rp!=null?`PIM Group-to-RP Mappings\n\nGroup(s): 224.0.0.0/4, Static\n    RP: ${ip4s(d.rp)} (?)`:"PIM Group-to-RP Mappings\n");
S("netconf-yang sessions",(d)=>d.extra.netconf?"R: Global-lock on running datastore\nC: Global-lock on candidate datastore\nS: Global-lock on startup datastore\n\nNumber of sessions : 0":"% NETCONF-YANG is not enabled. Configure netconf-yang first.");
S("platform software yang-management process",(d)=>[["confd","netconf"],["nesd","netconf"],["syncfd","netconf"],["ncsshd","netconf"],["dmiauthd","any"],["nginx","restconf"],["ndbmand","any"],["pubd","netconf"]].map(([p,k])=>pad(p,12)+": "+((k==="netconf"&&d.extra.netconf)||(k==="restconf"&&d.extra.restconf&&d.extra.https)||(k==="any"&&(d.extra.netconf||d.extra.restconf))?"Running":"Not Running")).join("\n"));

/* ---------- running-config sections ---------- */
IOS.cfgTop=(w,d)=>{const L=[];if(d.vrrpV3)L.push("fhrp version vrrp v3");
  Object.entries(d.vrfs).forEach(([n,v])=>{if(v.legacy){L.push("ip vrf "+n);if(v.rd)L.push(" rd "+v.rd);L.push("!");return}L.push("vrf definition "+n);if(v.rd)L.push(" rd "+v.rd);if(v.af4)L.push(" !"," address-family ipv4"," exit-address-family");L.push("!")});
  if(d.aaa){Object.entries(d.aaaGroups||{}).forEach(([n,g])=>{L.push(`aaa group server ${g.proto==="tacacs"?"tacacs+":"radius"} ${n}`);g.servers.forEach(s=>L.push(" server name "+s));L.push("!")});
    Object.entries(d.aaaLists||{}).forEach(([n,m])=>{if(n!=="default"&&!n.startsWith("__"))L.push(`aaa authentication login ${n} ${m.join(" ")}`)});if(d.aaaEnable)L.push("aaa authentication enable default "+d.aaaEnable);if(d.aaaCmdAcct)L.push(`aaa accounting commands ${d.aaaCmdAcct[0]} default start-stop group ${d.aaaCmdAcct[1]}`)}
  if(d.mcast)L.push("ip multicast-routing distributed");if(d.extra.loginBlock)L.push(`login block-for ${d.extra.loginBlock[0]} attempts ${d.extra.loginBlock[1]} within ${d.extra.loginBlock[2]}`);
  return L};
IOS.cfgPreIf=(w,d)=>{const L=[];const C2=d.crypto;
  Object.entries(d.tracks).forEach(([k,t])=>{L.push(t.type==="if"?`track ${k} interface ${t.if} ${t.mode}`:t.type==="sla"?`track ${k} ip sla ${t.sla} ${t.mode}`:`track ${k} ip route ${ip4s(t.n)} ${lenMask(t.len)} reachability`);if(t.delay)L.push(" delay "+t.delay);L.push("!")});
  Object.entries(C2.isakmp).forEach(([n,p])=>{L.push("crypto isakmp policy "+n);if(p.enc!=="des")L.push(" encryption "+p.enc);if(p.hash!=="sha")L.push(" hash "+p.hash);if(p.auth!=="rsa-sig")L.push(" authentication "+p.auth);if(p.group!==1)L.push(" group "+p.group);if(p.life!==86400)L.push(" lifetime "+p.life)});
  Object.entries(C2.keys).forEach(([a,k])=>L.push(`crypto isakmp key ${k} address ${ip4s(BigInt(a))}`));
  Object.entries(C2.ts).forEach(([n,t])=>{L.push(`crypto ipsec transform-set ${n} ${t.tf}`,` mode ${t.mode}`)});
  Object.entries(C2.prof).forEach(([n,p])=>{L.push("!","crypto ipsec profile "+n);if(p.ts)L.push(" set transform-set "+p.ts)});
  if(Object.keys(C2.isakmp).length||Object.keys(C2.prof).length)L.push("!");
  if(d.kind!=="router"&&(d.mst.name||d.mst.rev||Object.keys(d.mst.inst).length)){L.push("spanning-tree mst configuration");if(d.mst.name)L.push(" name "+d.mst.name);if(d.mst.rev)L.push(" revision "+d.mst.rev);Object.entries(d.mst.inst).forEach(([k,V])=>L.push(` instance ${k} vlan ${V.join(",")}`));L.push("!")}
  Object.entries(d.mstPri).forEach(([k,p])=>L.push(`spanning-tree mst ${k} priority ${p}`));
  Object.entries(d.fnf.rec).forEach(([n,R])=>{L.push("flow record "+n);R.match.forEach(m=>L.push(" match "+m));R.collect.forEach(m=>L.push(" collect "+m));L.push("!")});
  Object.entries(d.fnf.exp).forEach(([n,E])=>{L.push("flow exporter "+n);if(E.dst!=null)L.push(" destination "+ip4s(E.dst));if(E.src)L.push(" source "+E.src);if(E.port!==9995)L.push(" transport udp "+E.port);if(E.proto!=="netflow-v9")L.push(" export-protocol "+E.proto);L.push("!")});
  Object.entries(d.fnf.mon).forEach(([n,M])=>{L.push("flow monitor "+n);M.exp.forEach(e=>L.push(" exporter "+e));if(M.active!==1800)L.push(" cache timeout active "+M.active);if(M.inactive!==15)L.push(" cache timeout inactive "+M.inactive);if(M.rec)L.push(" record "+M.rec);L.push("!")});
  Object.entries(d.cmaps).forEach(([n,M])=>{L.push(`class-map ${M.any?"match-any":"match-all"} ${n}`);M.matches.forEach(m=>L.push(` match ${m.t}${m.v?" "+m.v:""}`));L.push("!")});
  Object.entries(d.pmaps).forEach(([n,P])=>{L.push("policy-map "+n);P.classes.forEach(c=>{L.push(" class "+c.cls);const A=c.act;
    if(A.priority)L.push("  priority"+(A.priority.level?" level "+A.priority.level:"")+(A.priority.pct!=null?" percent "+A.priority.pct:A.priority.kbps!=null?" "+A.priority.kbps:""));
    if(A.bandwidth)L.push("  bandwidth "+(A.bandwidth.rem!=null?"remaining percent "+A.bandwidth.rem:A.bandwidth.pct!=null?"percent "+A.bandwidth.pct:A.bandwidth.kbps));
    if(A.shape)L.push("  shape average "+(A.shape.pct!=null?"percent "+A.shape.pct:A.shape.avg));if(A.fq)L.push("  fair-queue");if(A.wred)L.push("  random-detect"+(A.wred==="dscp-based"?" dscp-based":""));
    if(A.police)L.push(`  police ${A.police.pps?"rate "+A.police.cir+" pps":A.police.cir} conform-action ${A.police.conform}${A.police.conformV?" "+A.police.conformV:""} exceed-action ${A.police.exceed}${A.police.exceedV?" "+A.police.exceedV:""}`);
    if(A.set)L.push("  set dscp "+A.set.dscp);if(A.drop)L.push("  drop");if(A.child)L.push("  service-policy "+A.child)});L.push("!")});
  return L};
IOS.ifCfgExtra=(w,d,i)=>{const L=[];const t=i.tun;
  if(i.mtu)L.push(" ip mtu "+i.mtu);if(i.mss)L.push(" ip tcp adjust-mss "+i.mss);
  if(i.ospf.auth)L.push(" ip ospf authentication"+(i.ospf.auth==="md5"?" message-digest":""));if(i.ospf.key)L.push(i.ospf.key.startsWith("p:")?" ip ospf authentication-key "+i.ospf.key.slice(2):` ip ospf message-digest-key ${i.ospf.key.split(":")[0]} md5 ${i.ospf.key.split(":").slice(1).join(":")}`);if(i.ospf.mtuIgn)L.push(" ip ospf mtu-ignore");
  if(i.policy)L.push(" ip policy route-map "+i.policy);if(i.pim)L.push(" ip pim "+i.pim);
  Object.entries(i.hsrp).forEach(([g,c])=>{(c.track||[]).forEach(x=>L.push(` standby ${g} track ${x.obj} decrement ${x.dec}`));if(c.timers)L.push(` standby ${g} timers ${c.timers[0]} ${c.timers[1]}`);if(c.auth)L.push(` standby ${g} authentication md5 key-string ${c.auth}`);if(c.name)L.push(` standby ${g} name ${c.name}`)});
  Object.entries(i.vrrp).forEach(([g,c])=>{if(c.v3){L.push(` vrrp ${g} address-family ipv4`);if(c.pri!=null)L.push("  priority "+c.pri);if(c.preempt===false)L.push("  no preempt");(c.track||[]).forEach(x=>L.push(`  track ${x.obj} decrement ${x.dec}`));if(c.ip!=null)L.push("  address "+ip4s(c.ip)+" primary");L.push("  exit-vrrp");return}(c.track||[]).forEach(x=>L.push(` vrrp ${g} track ${x.obj} decrement ${x.dec}`))});
  if(i.flowMon.in)L.push(` ip flow monitor ${i.flowMon.in} input`);if(i.flowMon.out)L.push(` ip flow monitor ${i.flowMon.out} output`);
  if(t){if(t.src!=null)L.push(" tunnel source "+(typeof t.src==="string"?t.src:ip4s(t.src)));if(t.dst!=null)L.push(" tunnel destination "+ip4s(t.dst));if(t.mode==="ipsec")L.push(" tunnel mode ipsec ipv4");if(t.mode==="mgre")L.push(" tunnel mode gre multipoint");if(t.prot)L.push(" tunnel protection ipsec profile "+t.prot)}
  if(i.keepalive)L.push(` keepalive ${i.keepalive[0]} ${i.keepalive[1]}`);
  if(i.svc.in)L.push(" service-policy input "+i.svc.in);if(i.svc.out)L.push(" service-policy output "+i.svc.out);
  return L};
IOS.ospfCfgExtra=(d,p)=>{const L=[];if(p.ad)L.push(" distance "+p.ad);Object.entries(p.areaAuth||{}).forEach(([a])=>L.push(` area ${a} authentication message-digest`));
  Object.entries(p.stubs||{}).forEach(([a,s])=>L.push(` area ${a} stub${s.nosum?" no-summary":""}`));Object.entries(p.ranges||{}).forEach(([a,R])=>R.forEach(r=>L.push(` area ${a} range ${ip4s(r.n)} ${lenMask(r.len)}${r.noAdv?" not-advertise":""}`)));
  if(p.redist?.static)L.push(" redistribute static subnets");if(p.redist?.connected)L.push(" redistribute connected subnets");return L};
IOS.cfgRouting=(w,d)=>{const L=[];const B=d.bgp;if(!B)return L;L.push("router bgp "+B.asn);if(B.rid!=null)L.push(" bgp router-id "+ip4s(B.rid));if(B.log)L.push(" bgp log-neighbor-changes");
  Object.entries(B.nbrs).forEach(([k,nb])=>{const ip=ip4s(BigInt(k));if(nb.ras!=null)L.push(` neighbor ${ip} remote-as ${nb.ras}`);if(nb.desc)L.push(` neighbor ${ip} description ${nb.desc}`);if(nb.pw)L.push(` neighbor ${ip} password ${nb.pw}`);if(nb.upd)L.push(` neighbor ${ip} update-source ${nb.upd}`);if(nb.multihop)L.push(` neighbor ${ip} ebgp-multihop ${nb.multihop}`);if(nb.shut)L.push(` neighbor ${ip} shutdown`)});
  L.push(" !"," address-family ipv4");B.nets.forEach(n=>L.push(`  network ${ip4s(n.n)} mask ${lenMask(n.len)}`));if(B.redistConnected)L.push("  redistribute connected");
  Object.entries(B.nbrs).forEach(([k,nb])=>{const ip=ip4s(BigInt(k));L.push(`  neighbor ${ip} activate`);if(nb.weight!=null)L.push(`  neighbor ${ip} weight ${nb.weight}`);if(nb.rmIn)L.push(`  neighbor ${ip} route-map ${nb.rmIn} in`);if(nb.rmOut)L.push(`  neighbor ${ip} route-map ${nb.rmOut} out`)});
  L.push(" exit-address-family","!");return L};
IOS.cfgEnd=(w,d)=>{const L=[];const X=d.ntpx;
  Object.entries(d.slas).forEach(([k,s])=>{L.push("ip sla "+k);if(s.dst!=null)L.push(` icmp-echo ${ip4s(s.dst)}${s.srcIf?" source-interface "+s.srcIf:""}`);if(s.freq!==60)L.push("  frequency "+s.freq);if(s.thr)L.push("  threshold "+s.thr);if(s.tmo)L.push("  timeout "+s.tmo);if(s.sched)L.push(`ip sla schedule ${k} life forever start-time now`)});
  Object.entries(d.plists).forEach(([n,P])=>P.forEach(e=>L.push(`ip prefix-list ${n} seq ${e.seq} ${e.act} ${ip4s(e.n)}/${e.len}${e.ge!=null?" ge "+e.ge:""}${e.le!=null?" le "+e.le:""}`)));if(Object.keys(d.plists).length)L.push("!");
  Object.entries(d.rmaps).forEach(([n,R])=>R.forEach(e=>{L.push(`route-map ${n} ${e.act} ${e.seq}`);e.match.forEach(m=>L.push(m.t==="pl"?` match ip address prefix-list ${m.v}`:` match ip address ${m.v}`));
    if(e.set.lp!=null)L.push(" set local-preference "+e.set.lp);if(e.set.weight!=null)L.push(" set weight "+e.set.weight);if(e.set.med!=null)L.push(" set metric "+e.set.med);if(e.set.prepend)L.push(" set as-path prepend "+e.set.prepend.join(" "));if(e.set.nh)L.push(" set ip next-hop "+e.set.nh.map(ip4s).join(" "));if(e.set.oif)L.push(" set interface "+e.set.oif);L.push("!")}));
  if(d.extra.netconf)L.push("netconf-yang");if(d.extra.restconf)L.push("restconf");if(d.extra.http)L.push("ip http server");if(d.extra.httpAuth)L.push("ip http authentication local");if(d.extra.https)L.push("ip http secure-server");
  if(d.logging.src)L.push("logging source-interface "+d.logging.src);if(d.rp!=null)L.push("ip pim rp-address "+ip4s(d.rp));
  if(d.cpSvc)L.push("!","control-plane"," service-policy input "+d.cpSvc,"!");
  Object.entries(d.mon).forEach(([k,M])=>{if(M.type==="erspan-src"){L.push(`monitor session ${k} type erspan-source`);if(M.src.length)L.push(" source interface "+M.src.map(s=>ifShort(s.if)).join(" , ")+(M.src[0].dir!=="both"?" "+M.src[0].dir:""));if(!M.er.shut)L.push(" no shutdown");L.push(" destination");if(M.er.id!=null)L.push("  erspan-id "+M.er.id);if(M.er.ip!=null)L.push("  ip address "+ip4s(M.er.ip));if(M.er.origin!=null)L.push("  origin ip address "+ip4s(M.er.origin));return}
    M.src.forEach(s=>L.push(`monitor session ${k} source interface ${ifShort(s.if)}${s.dir!=="both"?" "+s.dir:""}`));if(M.srcVlan)L.push(`monitor session ${k} source vlan ${M.srcVlan}${M.vdir&&M.vdir!=="both"?" "+M.vdir:""}`);if(M.srcRemote)L.push(`monitor session ${k} source remote vlan ${M.srcRemote}`);if(M.dst)L.push(`monitor session ${k} destination interface ${ifShort(M.dst)}${M.repl?" encapsulation replicate":""}`);if(M.dstVlan)L.push(`monitor session ${k} destination remote vlan ${M.dstVlan}`)});
  if(X.auth)L.push("ntp authenticate");Object.entries(X.keys).forEach(([k,v])=>L.push(`ntp authentication-key ${k} md5 ${v} 7`));X.trusted.forEach(k=>L.push("ntp trusted-key "+k));if(X.src)L.push("ntp source "+X.src);if(X.master!=null)L.push("ntp master"+(X.master!==8?" "+X.master:""));
  d.ntp.forEach(n=>L.push("ntp server "+ip4s(n)+(X.srvKey[String(n)]!=null?" key "+X.srvKey[String(n)]:"")));
  Object.entries(d.eem).forEach(([n,A])=>{L.push("event manager applet "+n);if(A.desc)L.push(` description "${A.desc}"`);if(A.ev)L.push(A.ev.t==="none"?" event none":A.ev.t==="syslog"?` event syslog pattern "${A.ev.pat}"`:A.ev.t==="track"?` event track ${A.ev.id} state ${A.ev.state}`:A.ev.t==="timer"?" event timer "+A.ev.spec:A.ev.t==="cli"?` event cli pattern "${A.ev.pat}" sync no skip no`:" event "+A.ev.t);
    [...A.acts].forEach(x=>L.push(x.t==="cli"?` action ${x.lbl} cli command "${x.cmd}"`:x.t==="syslog"?` action ${x.lbl} syslog msg "${x.msg}"`:x.t==="wait"?` action ${x.lbl} wait ${x.n}`:` action ${x.lbl} ${x.t} ${x.rest||""}`))});
  return L};
})();
